contract.content:
{
  "action": "execute",
  "archetype": "ai-tool",
  "message": "I'll build a clause extraction tool where reviewers upload vendor agreements and AI extracts structured terms — renewal dates, pricing adjustments, compliance obligations, and unusual clauses — with citations back to the source. Reviewers can search and filter across all extracted clauses, flag items for follow-up, and receive email notifications when extractions complete or high-risk clauses are detected. Admins get an oversight dashboard and can export data as CSV. All actions are audit-logged.",
  "flags": ["has-users", "has-admin", "ai-chat", "file-uploads", "search-ui", "notifications-email", "exports-csv"],
  "tasks": [
    {
      "scope": "database",
      "summary": "Set up storage for users, vendors, uploaded contracts, the structured clauses pulled from them, reviewer annotations, and an audit trail.",
      "task": "Tables: users, vendors, contracts, extracted_clauses, clause_annotations, audit_logs. Indexes on FKs and on extracted_clauses(clause_type, contract_id), audit_logs(created_at DESC). Column-level contract: data_model.",
      "dockerfile": "Dockerfile.postgres",
      "rules": [],
      "snippets": []
    },
    {
      "scope": "vectordb",
      "summary": "Set up a semantic search index so reviewers can find clauses by meaning across all extracted contract data.",
      "task": "pgvector extension. Table: doc_chunks(id, contract_id, clause_id NULL, chunk_text TEXT, embedding vector(3072), metadata JSONB). HNSW index on embedding (cosine). Embedding model: text-embedding-3-large via MGA.",
      "dockerfile": "Dockerfile.pgvector",
      "rules": [],
      "snippets": [],
      "primarySnippet": "vectordb/vectordb-connections.ts"
    },
    {
      "scope": "backend",
      "summary": "Build the API that accepts contract uploads, runs AI clause extraction, stores structured results, supports search/filter/annotate, sends email alerts, and exports CSV.",
      "task": "Data: pg Pool from env. Endpoints + bodies: api_contract. Behaviors + rules + side-effects: business_logic_contract. Auth: x-amzn-oidc-data JWT sub/email; create users row on first login. File uploads: multer memory storage only — parse PDF/DOCX in-memory, send text to MGA assistant for extraction, persist structured clauses to Postgres and chunk-embeddings to pgvector; do NOT write raw files to disk. Email notifications on extraction-complete and high-risk-clause-detected. CSV export streams extracted_clauses with filters. Admin endpoints require role='admin'. Audit log every write.",
      "dockerfile": "Dockerfile.node",
      "rules": [],
      "snippets": [],
      "primarySnippet": "backend/express-server-template.ts"
    },
    {
      "scope": "frontend",
      "summary": "Build the reviewer UI: upload contracts, see extracted clauses in a structured table with source citations, search/filter across clauses, flag and annotate, plus an admin oversight view.",
      "task": "Views + components: ui_contract. Endpoints + body shapes: api_contract (prepend /api/). States: spinner during upload+extraction, empty CTA on no contracts, toast on 4xx/5xx, 404 page, disabled submit during POST, progress indicator while AI extracts. Responsive.",
      "dockerfile": "Dockerfile.react",
      "rules": [],
      "snippets": [],
      "primarySnippet": "frontend/AppScaffold.tsx"
    },
    {
      "scope": "integration",
      "summary": "Wire all services together so the app runs locally with one command.",
      "task": "Wire database, vectordb, backend, frontend. Backend env: DATABASE_HOST=database, DATABASE_PORT=5432, DATABASE_NAME=clauses, DATABASE_USER=clauses_user, DATABASE_PASSWORD=localdev123, VECTORDB_HOST=vectordb, VECTORDB_PORT=5432. nginx.local.conf proxy /api→backend:3000. depends_on chain frontend→backend→{database,vectordb}. Healthchecks. Named volumes for database and vectordb.",
      "rules": [],
      "snippets": [],
      "primarySnippet": "integration/docker-compose-fullstack.yml"
    }
  ],
  "data_model": {
    "tables": [
      {
        "name": "users",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "oidc_sub", "type": "TEXT UNIQUE NOT NULL"},
          {"name": "email", "type": "VARCHAR(255) NOT NULL"},
          {"name": "role", "type": "VARCHAR(32) NOT NULL DEFAULT 'reviewer'"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "vendors",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "name", "type": "VARCHAR(255) NOT NULL"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "contracts",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "user_id", "type": "INTEGER NOT NULL REFERENCES users(id)"},
          {"name": "vendor_id", "type": "INTEGER REFERENCES vendors(id)"},
          {"name": "title", "type": "VARCHAR(500) NOT NULL"},
          {"name": "original_filename", "type": "VARCHAR(500) NOT NULL"},
          {"name": "mime_type", "type": "VARCHAR(100)"},
          {"name": "status", "type": "VARCHAR(32) NOT NULL DEFAULT 'pending'"},
          {"name": "extracted_text", "type": "TEXT"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"},
          {"name": "extracted_at", "type": "TIMESTAMPTZ"}
        ]
      },
      {
        "name": "extracted_clauses",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "contract_id", "type": "INTEGER NOT NULL REFERENCES contracts(id) ON DELETE CASCADE"},
          {"name": "clause_type", "type": "VARCHAR(64) NOT NULL"},
          {"name": "clause_text", "type": "TEXT NOT NULL"},
          {"name": "structured_value", "type": "JSONB"},
          {"name": "citation_excerpt", "type": "TEXT"},
          {"name": "citation_location", "type": "VARCHAR(255)"},
          {"name": "risk_level", "type": "VARCHAR(16) NOT NULL DEFAULT 'normal'"},
          {"name": "is_unusual", "type": "BOOLEAN NOT NULL DEFAULT FALSE"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "clause_annotations",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "clause_id", "type": "INTEGER NOT NULL REFERENCES extracted_clauses(id) ON DELETE CASCADE"},
          {"name": "user_id", "type": "INTEGER NOT NULL REFERENCES users(id)"},
          {"name": "note", "type": "TEXT NOT NULL"},
          {"name": "flagged", "type": "BOOLEAN NOT NULL DEFAULT FALSE"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      },
      {
        "name": "audit_logs",
        "columns": [
          {"name": "id", "type": "SERIAL PRIMARY KEY"},
          {"name": "user_id", "type": "INTEGER REFERENCES users(id)"},
          {"name": "action", "type": "VARCHAR(64) NOT NULL"},
          {"name": "entity_type", "type": "VARCHAR(64)"},
          {"name": "entity_id", "type": "INTEGER"},
          {"name": "details", "type": "JSONB"},
          {"name": "created_at", "type": "TIMESTAMPTZ NOT NULL DEFAULT NOW()"}
        ]
      }
    ]
  },
  "api_contract": {
    "version": 1,
    "endpoints": [
      {
        "method": "GET",
        "path": "/whoami",
        "response": {"status": 200, "body": "{ id, email, role }"}
      },
      {
        "method": "GET",
        "path": "/vendors",
        "response": {"status": 200, "body": "{ vendors: [{ id, name }] }"}
      },
      {
        "method": "POST",
        "path": "/vendors",
        "request": {"name": "string required"},
        "response": {"status": 201, "body": "{ id, name }"}
      },
      {
        "method": "POST",
        "path": "/contracts",
        "request": "multipart/form-data: file (PDF/DOCX) required, title string required, vendor_id integer optional",
        "response": {"status": 201, "body": "{ id, title, status, vendor_id }"}
      },
      {
        "method": "GET",
        "path": "/contracts",
        "request": "query: limit=50, offset=0, vendor_id?, status?",
        "response": {"status": 200, "body": "{ contracts: [{ id, title, vendor_id, status, created_at, extracted_at }], total }"}
      },
      {
        "method": "GET",
        "path": "/contracts/:id",
        "response": {"status": 200, "body": "{ id, title, vendor_id, status, original_filename, extracted_text, created_at, extracted_at }"}
      },
      {
        "method": "GET",
        "path": "/contracts/:id/clauses",
        "response": {"status": 200, "body": "{ clauses: [{ id, clause_type, clause_text, structured_value, citation_excerpt, citation_location, risk_level, is_unusual }] }"}
      },
      {
        "method": "GET",
        "path": "/clauses",
        "request": "query: limit=50, offset=0, clause_type?, risk_level?, is_unusual?, vendor_id?, q?",
        "response": {"status": 200, "body": "{ clauses: [{ id, contract_id, contract_title, vendor_id, clause_type, clause_text, structured_value, citation_excerpt, citation_location, risk_level, is_unusual }], total }"}
      },
      {
        "method": "POST",
        "path": "/clauses/:id/annotations",
        "request": {"note": "string required", "flagged": "boolean optional"},
        "response": {"status": 201, "body": "{ id, clause_id, note, flagged, created_at }"}
      },
      {
        "method": "GET",
        "path": "/clauses/:id/annotations",
        "response": {"status": 200, "body": "{ annotations: [{ id, user_id, note, flagged, created_at }] }"}
      },
      {
        "method": "GET",
        "path": "/clauses/export.csv",
        "request": "query: clause_type?, risk_level?, vendor_id?",
        "response": {"status": 200, "body": "text/csv stream of extracted clauses with citations"}
      },
      {
        "method": "GET",
        "path": "/admin/stats",
        "response": {"status": 200, "body": "{ total_contracts, total_clauses, total_users, flagged_clauses, high_risk_clauses, extractions_last_7d }"}
      },
      {
        "method": "GET",
        "path": "/admin/audit-logs",
        "request": "query: limit=50, offset=0",
        "response": {"status": 200, "body": "{ logs: [{ id, user_id, action, entity_type, entity_id, details, created_at }], total }"}
      }
    ]
  },
  "ui_contract": {
    "primary_view": "list of uploaded contracts with extraction status",
    "primary_action": "upload a vendor agreement for clause extraction",
    "secondary_views": [
      "contract detail with structured clauses table and source citations",
      "global clause search and filter across all contracts",
      "flagged and annotated clauses view",
      "admin dashboard with usage stats and audit log",
      "CSV export"
    ],
    "components": [
      {"name": "ContractUploader", "role": "drag-and-drop upload form for PDF/DOCX vendor agreements"},
      {"name": "ContractList", "role": "table of uploaded contracts with vendor, status, and extracted_at"},
      {"name": "ContractDetail", "role": "shows contract metadata and the structured clause table"},
      {"name": "ClauseTable", "role": "structured table of extracted clauses grouped by type with risk indicators"},
      {"name": "ClauseCitation", "role": "shows the source excerpt and location for a clause"},
      {"name": "ClauseSearch", "role": "search and filter UI across all extracted clauses"},
      {"name": "ClauseFilters", "role": "filter chips for clause_type, risk_level, unusual, vendor"},
      {"name": "AnnotationPanel", "role": "add notes and flag a clause for follow-up"},
      {"name": "FlaggedClausesView", "role": "list of clauses flagged by reviewers"},
      {"name": "ExtractionStatusBadge", "role": "shows pending / extracting / complete / failed state"},
      {"name": "AdminDashboard", "role": "usage stats, high-risk counts, and audit log for admins"},
      {"name": "ExportCsvButton", "role": "triggers CSV download with current filters applied"}
    ]
  },
  "business_logic_contract": {
    "triggers": [
      {"event": "user_first_login", "action": "create users row from OIDC sub/email, default role='reviewer'"},
      {"event": "contract_uploaded", "action": "parse PDF/DOCX text in-memory, set status='extracting', invoke MGA extraction assistant, persist extracted_clauses with citations, chunk+embed text into pgvector doc_chunks, set status='complete' and extracted_at=NOW()"},
      {"event": "extraction_completed", "action": "send email notification to uploading reviewer with summary of extracted clauses"},
      {"event": "high_risk_clause_detected", "action": "mark clause risk_level='high', send email alert to uploading reviewer"},
      {"event": "unusual_clause_detected", "action": "set extracted_clauses.is_unusual=true based on cross-contract comparison"},
      {"event": "extraction_failed", "action": "set contracts.status='failed', email reviewer"}
    ],
    "rules": [
      "all endpoints require authenticated user via x-amzn-oidc-data JWT",
      "reviewers can upload contracts and view/annotate any clause across the org",
      "reviewers can only edit/delete their own annotations",
      "/admin/* endpoints require users.role='admin'",
      "/clauses/export.csv accessible to reviewers and admins",
      "raw uploaded file bytes are NEVER persisted to disk — only extracted text and structured clauses stored",
      "all POST/PUT/DELETE write actions write an audit_logs row"
    ],
    "side_effects": [
      "audit log on every write",
      "email notification on extraction complete and on high-risk clause detection",
      "pgvector embeddings written alongside extracted_clauses for semantic search"
    ]
  },
  "vector_engine": "pgvector",
  "mga_assistants": [
    {
      "key": "default",
      "name": "Clause Extraction Assistant",
      "description": "Extracts structured clauses (renewal terms, pricing adjustments, compliance obligations, unusual provisions) from vendor agreements and returns them with source citations and risk assessment.",
      "model": "claude-opus-4.7",
      "tool_keys": [],
      "starter_messages": [
        "Extract all renewal and termination terms from this contract.",
        "What pricing adjustment clauses are in this agreement?",
        "Flag any unusual or high-risk obligations in this vendor contract."
      ]
    }
  ]
}
